//! English adjectives: 13 declensions learned from 61,453 dictionary words, the rules on a
//! word's ending that choose one, and the forms no declension gives.
//!
//! Generated by flexion-train from Wiktionary; don't edit by hand.

mod irregular;
mod laws;
mod paradigms;
mod relations;
mod rules;
mod spellings;
mod stems;

pub use paradigms::Declension;

use flexion::{Candidate, Grammar, Known, Reading};
use std::borrow::Cow;

/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const ADJECTIVE_POS: u16 = 0;
    pub const ADJECTIVE_COMP: u16 = 1;
    pub const ADJECTIVE_SUP: u16 = 2;
}

/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Declension> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 3,
    lemma_cell: Some(0),
    capitalized: false,
    paradigms: Cow::Borrowed(&paradigms::DECLENSIONS),
    paradigm: rules::DECLENSION,
    relations: Cow::Borrowed(&relations::RELATIONS),
    feature: None,
    compound: None,
    prefixes: None,
    heads: flexion::Heads {
        least: None,
        not: Cow::Borrowed(&[]),
        words: Cow::Borrowed(&[]),
    },
    accent: None,
    laws: Some(laws::LAWS),
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    marks: None,
    slots: Cow::Borrowed(&stems::SLOTS),
    tables: Cow::Borrowed(&stems::TABLES),
    irregular: irregular::IRREGULAR,
    smoothing: 2.0,
    sharpness: 0.75,
    trust: flexion::Trust {
        regular: 1.0,
        unsettled: 0.99838084,
        unattested: 1.0,
    },
};

/// A adjective form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// An adjective in the given degree.
    Form(crate::Degree),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        use crate::Degree::*;
        let cell = match self {
            Cell::Form(Positive) => cell::ADJECTIVE_POS,
            Cell::Form(Comparative) => cell::ADJECTIVE_COMP,
            Cell::Form(Superlative) => cell::ADJECTIVE_SUP,
        };
        cell as usize
    }
}

impl From<crate::Degree> for Cell {
    fn from(degree: crate::Degree) -> Self {
        Cell::Form(degree)
    }
}

/// A adjective to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Adjective<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Adjective<'w> {
    /// The adjective `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Adjective {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
